from __future__ import annotations

import os
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "scripts"))

import pip_lock_subset as pls  # noqa: E402

LOCK = """\
# This file was autogenerated by uv
azure-core==1.41.0 \\
    --hash=sha256:aaa \\
    --hash=sha256:bbb
    # via azure-identity
Jinja2==3.1.6 \\
    --hash=sha256:ccc
    # via ansible-core
cffi==2.1.1 ; platform_python_implementation != 'PyPy' \\
    --hash=sha256:ddd
requests==2.34.2 \\
    --hash=sha256:eee
"""

INSTALLED = "cffi==2.1.1\nrequests==2.34.2\npip==26.2.2\nwheel==0.48.0\n"


class TestPipLockSubset(unittest.TestCase):
    def test_normalize(self):
        self.assertEqual(pls.normalize("Typing_Extensions"), "typing-extensions")
        self.assertEqual(pls.normalize("ruamel.yaml"), "ruamel-yaml")

    def test_installed_names_ignore_noise(self):
        self.assertEqual(
            pls.installed_names("Jinja2==3.1\n\n# comment\n-e git+x\nrequests==2"),
            {"jinja2", "requests"},
        )

    def test_parse_lock_keeps_markers_and_hashes_and_drops_comments(self):
        entries = dict(pls.parse_lock(LOCK))
        self.assertEqual(set(entries), {"azure-core", "jinja2", "cffi", "requests"})
        self.assertEqual(
            entries["azure-core"][1:], ["    --hash=sha256:aaa \\", "    --hash=sha256:bbb"]
        )
        self.assertIn("; platform_python_implementation != 'PyPy'", entries["cffi"][0])
        self.assertFalse(any("# via" in line for lines in entries.values() for line in lines))

    def test_subset_returns_only_missing_packages_with_hashes(self):
        result = pls.subset(LOCK, INSTALLED)
        self.assertIn("azure-core==1.41.0", result)
        self.assertIn("Jinja2==3.1.6", result)
        self.assertIn("--hash=sha256:bbb", result)
        self.assertNotIn("cffi", result)
        self.assertNotIn("requests", result)

    def test_every_package_present_gives_empty_output(self):
        freeze = "azure-core==1\njinja2==3\ncffi==2\nrequests==2\n"
        self.assertEqual(pls.subset(LOCK, freeze), "")

    def test_empty_lock(self):
        self.assertEqual(pls.subset("# nothing\n", INSTALLED), "")

    def test_the_real_windows_lock_parses_and_every_entry_has_hashes(self):
        root = os.path.join(os.path.dirname(__file__), "..")
        with open(os.path.join(root, "requirements-windows.txt"), encoding="utf-8") as handle:
            entries = list(pls.parse_lock(handle.read()))
        self.assertGreater(len(entries), 10)
        for name, lines in entries:
            self.assertTrue(any(line.strip().startswith("--hash=") for line in lines), name)

    def test_main_prints_the_subset_and_validates_arguments(self):
        import contextlib
        import io

        with tempfile.TemporaryDirectory() as tmp:
            lock, freeze = os.path.join(tmp, "lock.txt"), os.path.join(tmp, "freeze.txt")
            with open(lock, "w") as handle:
                handle.write(LOCK)
            with open(freeze, "w") as handle:
                handle.write(INSTALLED)
            out = io.StringIO()
            with contextlib.redirect_stdout(out):
                self.assertEqual(pls.main(["x", lock, freeze]), 0)
            self.assertIn("azure-core==1.41.0", out.getvalue())
        with contextlib.redirect_stderr(io.StringIO()):
            self.assertEqual(pls.main(["x"]), 2)


class TestSkip(unittest.TestCase):
    def test_skipped_names_are_left_out_even_when_missing(self):
        result = pls.subset(LOCK, INSTALLED, skip=["Azure_Core"])
        self.assertNotIn("azure-core", result)
        self.assertIn("Jinja2==3.1.6", result)

    def test_main_accepts_skip_arguments(self):
        import contextlib
        import io

        with tempfile.TemporaryDirectory() as tmp:
            lock, freeze = os.path.join(tmp, "lock.txt"), os.path.join(tmp, "freeze.txt")
            with open(lock, "w") as handle:
                handle.write(LOCK)
            with open(freeze, "w") as handle:
                handle.write(INSTALLED)
            out = io.StringIO()
            with contextlib.redirect_stdout(out):
                self.assertEqual(pls.main(["x", lock, freeze, "--skip", "azure-core", "jinja2"]), 0)
            self.assertEqual(out.getvalue(), "")
            with contextlib.redirect_stderr(io.StringIO()):
                self.assertEqual(pls.main(["x", lock, freeze, "--other"]), 2)


if __name__ == "__main__":
    unittest.main()
